//! Replay API, Rust implementation: an Axum 0.8 router inside a Cloudflare Worker (workers-rs), with the contract's
//! types generated by typify (`contract` crate) and Neon serverless SQL over HTTP for data.
//!
//! The request pipeline (`fetch`): request context and per-IP limit, then the Axum router, then `finish`, which adds
//! the §4 headers, Cache-Control by resource class, renders problem documents and asks the runtime to compress.

use std::sync::{Arc, OnceLock};

use axum::Router;
use axum::body::Body;
use axum::response::{IntoResponse, Response};
use axum::routing::{any, get};
use http::{HeaderValue, Method, StatusCode, header};
use tower_service::Service;
use worker::{Context, Env, HttpRequest, event};

pub mod app;
pub mod live;
pub mod meta;
pub mod neon;
pub mod places;
pub mod rows;
pub mod sql;
pub mod storms;
pub mod web;

use app::{App, CONTRACT_VERSION, Config, IMPL, IMPL_VERSION};
use web::{Ctx, Problem};

/// The router: the contract's 15 paths plus the test hook. Unknown paths are 404 and other methods 405, both as
/// problem+json; `get` also answers HEAD.
fn router(app: Arc<App>) -> Router {
    Router::new()
        .route("/healthz", get(meta::health))
        .route("/readyz", get(meta::readiness))
        .route("/v1/meta", get(meta::meta))
        .route("/v1/openapi.json", get(meta::openapi))
        .route("/v1/storms", get(storms::list))
        .route("/v1/storms/{sid}", get(storms::detail))
        .route("/v1/storms/{sid}/track", get(storms::track))
        .route("/v1/storms/{sid}/places", get(storms::places))
        .route("/v1/places/search", get(places::search))
        .route("/v1/places/nearest", get(places::nearest))
        .route("/v1/places/{placeId}", get(places::detail))
        .route("/v1/places/{placeId}/storms", get(places::storms))
        .route("/v1/hits", get(places::point))
        .route("/v1/live/storms", get(live::snapshot))
        .route("/v1/live/stream", get(live::stream))
        .route("/v1/_test/live-events", any(live::hook))
        .fallback(|| async { Problem::missing("No such resource.") })
        .method_not_allowed_fallback(|method: Method| async move {
            if method == Method::OPTIONS {
                return options("GET, HEAD, OPTIONS");
            }
            Problem::new(
                web::METHOD_NOT_ALLOWED,
                format!("Method {method} is not supported here."),
            )
            .header("Allow", "GET, HEAD, OPTIONS")
            .into_response()
        })
        .with_state(app)
}

/// 204 for OPTIONS with the methods a path allows.
pub fn options(allow: &'static str) -> Response {
    let mut res = Response::new(Body::empty());
    *res.status_mut() = StatusCode::NO_CONTENT;
    res.headers_mut().insert(header::ALLOW, HeaderValue::from_static(allow));
    res
}

fn var(env: &Env, name: &str) -> String {
    env.secret(name)
        .map(|s| s.to_string())
        .or_else(|_| env.var(name).map(|v| v.to_string()))
        .unwrap_or_default()
        .trim()
        .to_string()
}

/// When this isolate started serving (isolate-wide, not request state): `/v1/meta` `startedAt`.
static STARTED_AT: OnceLock<String> = OnceLock::new();

fn started_at() -> String {
    STARTED_AT
        .get_or_init(|| {
            let ms = worker::Date::now().as_millis() as i64;
            chrono::DateTime::from_timestamp_millis(ms - ms % 1000)
                .unwrap_or_default()
                .to_rfc3339_opts(chrono::SecondsFormat::Secs, true)
        })
        .clone()
}

#[event(fetch)]
async fn fetch(req: HttpRequest, env: Env, _cx: Context) -> worker::Result<worker::web_sys::Response> {
    let t0 = worker::Date::now().as_millis();
    let (mut parts, body) = req.into_parts();
    let ctx = Arc::new(Ctx::new(parts.method.clone(), &parts.uri, &parts.headers));
    let cfg = Config {
        site_origin: var(&env, "TR_SITE_ORIGIN"),
        test_hooks: var(&env, "TR_TEST_HOOKS") == "1",
        commit: Some(var(&env, "TR_COMMIT"))
            .filter(|c| !c.is_empty())
            .unwrap_or_else(|| "dev".into()),
        edge_secret: var(&env, "TR_EDGE_SECRET"),
        rate_limit: var(&env, "TR_RATE_LIMIT_PER_MINUTE") != "0",
    };
    let neon_http = var(&env, "NEON_HTTP_URL");
    let db = neon::Neon::new(&var(&env, "DATABASE_URL"), Some(neon_http.as_str()));

    let res = match rate_limit(&env, &cfg, &ctx, &parts.headers).await {
        Some(problem) => problem.into_response(),
        None => {
            let app = Arc::new(App::new(cfg, db, started_at()));
            parts.extensions.insert(ctx.clone());
            let req = http::Request::from_parts(parts, body);
            match router(app).call(req).await {
                Ok(res) => res,
                Err(never) => match never {},
            }
        }
    };
    let res = finish(&ctx, res).await;
    let line = serde_json::json!({
        "ts": app::now_rfc3339(), "level": "info", "msg": "request", "requestId": ctx.request_id, "impl": IMPL,
        "method": ctx.method.as_str(), "path": ctx.path, "status": res.status(),
        "durMs": worker::Date::now().as_millis() - t0,
    });
    worker::console_log!("{line}");
    Ok(res)
}

/// The per-IP limit (Workers rate limiting binding `RATE_LIMITER`): the edge proxy's own limit comes first; this one
/// guards the public workers.dev URL. Off when TR_RATE_LIMIT_PER_MINUTE=0 (CI), never on the probes.
async fn rate_limit(env: &Env, cfg: &Config, ctx: &Ctx, headers: &http::HeaderMap) -> Option<Problem> {
    if !cfg.rate_limit || ctx.path == "/healthz" || ctx.path == "/readyz" {
        return None;
    }
    let limiter = env.rate_limiter("RATE_LIMITER").ok()?;
    let outcome = limiter.limit(client_ip(cfg, headers)).await.ok()?;
    (!outcome.success).then(|| {
        Problem::new(web::RATE_LIMITED, "Too many requests from this address; retry later.").header("Retry-After", "60")
    })
}

/// Behind the edge proxy (proved by `X-Edge-Secret`) the first `X-Forwarded-For` entry; otherwise the connecting
/// client as Cloudflare reports it.
fn client_ip(cfg: &Config, headers: &http::HeaderMap) -> String {
    let get = |n: &str| headers.get(n).and_then(|v| v.to_str().ok()).unwrap_or("").trim();
    let sent = get("x-edge-secret");
    if !cfg.edge_secret.is_empty()
        && constant_time_eq(sent.as_bytes(), cfg.edge_secret.as_bytes())
        && let Some(first) = get("x-forwarded-for")
            .split(',')
            .next()
            .map(str::trim)
            .filter(|s| !s.is_empty())
    {
        return first.to_string();
    }
    Some(get("cf-connecting-ip"))
        .filter(|s| !s.is_empty())
        .unwrap_or("unknown")
        .to_string()
}

fn constant_time_eq(a: &[u8], b: &[u8]) -> bool {
    a.len() == b.len() && a.iter().zip(b).fold(0u8, |acc, (x, y)| acc | (x ^ y)) == 0
}

/// Bodies over 1 KB are compressed when the client accepts it (CONTRACT-GUIDE §4). Setting `Content-Encoding` hands
/// the work to the Workers runtime, which encodes the body natively (no wasm CPU).
const COMPRESS_MIN: usize = 1024;

/// The response as sent: problem documents rendered, the §4 headers, Cache-Control by resource class, compression,
/// and the conversion to a Workers response.
async fn finish(ctx: &Ctx, mut res: Response) -> worker::web_sys::Response {
    let status = res.status().as_u16();
    let problem = res.extensions_mut().remove::<Problem>();
    if let Some(p) = &problem {
        *res.body_mut() = Body::from(p.document(ctx.instance(), &ctx.request_id));
        let h = res.headers_mut();
        h.insert(
            header::CONTENT_TYPE,
            HeaderValue::from_static("application/problem+json"),
        );
        for (name, value) in &p.headers {
            if let Ok(v) = HeaderValue::from_str(value) {
                h.insert(*name, v);
            }
        }
    }
    let streaming = res.extensions().get::<live::Streaming>().is_some();
    let h = res.headers_mut();
    for (name, value) in [
        ("x-backend-impl", IMPL),
        ("x-backend-version", IMPL_VERSION),
        ("x-contract-version", CONTRACT_VERSION),
        ("vary", "Accept-Encoding"),
        ("x-content-type-options", "nosniff"),
        ("x-frame-options", "DENY"),
    ] {
        h.insert(name, HeaderValue::from_static(value));
    }
    if let Ok(id) = HeaderValue::from_str(&ctx.request_id) {
        h.insert("x-request-id", id);
    }
    if !h.contains_key(header::CACHE_CONTROL) {
        h.insert(
            header::CACHE_CONTROL,
            HeaderValue::from_static(web::cache_control(status, &ctx.method, &ctx.path)),
        );
    }
    h.remove(header::CONTENT_LENGTH);

    if streaming {
        return worker::response_to_wasm(res).unwrap_or_else(|_| fallback());
    }
    let (parts, body) = res.into_parts();
    let bytes = axum::body::to_bytes(body, usize::MAX).await.unwrap_or_default();
    let head = ctx.method == Method::HEAD || status == 304 || status == 204;
    let mut init = worker::ResponseBuilder::new().with_status(status);
    let headers = worker::Headers::new();
    for (name, value) in &parts.headers {
        if let Ok(v) = value.to_str() {
            let _ = headers.append(name.as_str(), v);
        }
    }
    if !head
        && bytes.len() > COMPRESS_MIN
        && let Some(enc) = encoding_for(&ctx.accept_encoding)
    {
        let _ = headers.set("content-encoding", enc);
    }
    init = init.with_headers(headers);
    let body = if head {
        None
    } else {
        Some(worker::js_sys::Uint8Array::from(bytes.as_ref()))
    };
    let init: worker::web_sys::ResponseInit = init.into();
    worker::web_sys::Response::new_with_opt_buffer_source_and_init(body.as_ref().map(|b| b.as_ref()), &init)
        .unwrap_or_else(|_| fallback())
}

/// gzip when accepted (the contract's MUST), else br.
fn encoding_for(accept: &str) -> Option<&'static str> {
    let accepts = |coding: &str| {
        accept.split(',').any(|part| {
            let mut it = part.split(';');
            let name = it.next().unwrap_or("").trim();
            let q = it
                .find_map(|p| p.trim().strip_prefix("q="))
                .and_then(|q| q.trim().parse::<f32>().ok())
                .unwrap_or(1.0);
            (name.eq_ignore_ascii_case(coding) || name == "*") && q > 0.0
        })
    };
    if accepts("gzip") {
        Some("gzip")
    } else if accepts("br") {
        Some("br")
    } else {
        None
    }
}

fn fallback() -> worker::web_sys::Response {
    worker::web_sys::Response::new_with_opt_str_and_init(None, &{
        let init = worker::web_sys::ResponseInit::new();
        init.set_status(500);
        init
    })
    .expect("a bare 500 response")
}
